content:
(() => {
  'use strict';

  const AVS = {
    version: '2.5.1',
    schemaVersion: '2.5.1',
    namespace: 'acgn_visual_v25',
    legacyNamespaces: ['acgn_visual_v24','acgn_visual_v23','acgn_visual_v22','acgn_visual_v21','acgn_visual_v2'],
    captureKey: 'avs_v25_capture',
    promptIds: {
      continuity: 'avs.v21.continuity',
      visibleGuard: 'avs.v21.visible_guard'
    },
    session: {
      processing: new Set(),
      backgroundCalls: new Set(),
      backgroundDepth: 0,
      queue: Promise.resolve(),
      health: 'READY',
      lastError: null,
      lastErrorStage: null,
      listeners: [],
      watchdog: null,
      retryTimers: new Map(),
      lastCardBootstrapAt: 0,
      schemaSupport: 'unknown',
      lastGenerationEndedId: null
    },
    limits: {
      watchdogIntervalMs: 1800,
      cardBootstrapIntervalMs: 30000,
      maxNewCharactersPerSync: 24,
      maxTrackedCharactersInPrompt: 64,
      backgroundTimeoutMs: 240000,
      backgroundMaxTokens: 16384,
      messageReadyTimeoutMs: 8000,
      recentTranscriptMessages: 12
    }
  };

  if (globalThis.__AVS_V25_RUNTIME__) {
    try { globalThis.__AVS_V25_RUNTIME__.stop?.(); } catch (_) {}
  }
  globalThis.__AVS_V25_RUNTIME__ = AVS;

  const now = () => new Date().toISOString();
  const clone = x => typeof structuredClone === 'function' ? structuredClone(x) : JSON.parse(JSON.stringify(x));
  const safeJson = x => JSON.stringify(x, null, 2);

  function hashString(input) {
    let h = 2166136261;
    const s = String(input ?? '');
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return (h >>> 0).toString(16).padStart(8, '0');
  }

  function semverParts(s) {
    return String(s || '').match(/\d+/g)?.slice(0,3).map(Number) || [0,0,0];
  }

  function semverGte(a,b) {
    const A=semverParts(a), B=semverParts(b);
    for (let i=0;i<3;i++) {
      if ((A[i]||0) > (B[i]||0)) return true;
      if ((A[i]||0) < (B[i]||0)) return false;
    }
    return true;
  }

  function helperVersion() {
    try { return String(getTavernHelperVersion?.() || 'unknown'); } catch (_) { return 'unknown'; }
  }

  function ctx() {
    try {
      const s = globalThis.SillyTavern;
      if (!s) return null;
      const c = s.getContext?.();
      return c && typeof c === 'object' ? {...s, ...c} : s;
    } catch (_) { return null; }
  }

  function hasCharacterContext() {
    const s=ctx();
    if (!s) return false;
    if (String(s.groupId ?? '').trim()) return true;
    const raw=s.characterId;
    if (raw===undefined || raw===null || String(raw).trim()==='') return false;
    const idx=Number(raw);
    return Number.isInteger(idx) && idx>=0 && !!s.characters?.[idx];
  }

  function currentCardInfo() {
    const s=ctx();
    if (!s) return null;
    if (String(s.groupId ?? '').trim()) {
      return {type:'group',id:String(s.groupId),name:String(s.name2||'群聊'),description:'',personality:'',scenario:'',first_mes:''};
    }
    const idx=Number(s.characterId);
    const card=Number.isInteger(idx)&&idx>=0?s.characters?.[idx]:null;
    if (!card) return null;
    return {
      type:'character',
      id:String(card.avatar ?? idx),
      name:String(card.name ?? s.name2 ?? '未命名'),
      description:String(card.description ?? card.data?.description ?? ''),
      personality:String(card.personality ?? card.data?.personality ?? ''),
      scenario:String(card.scenario ?? card.data?.scenario ?? ''),
      first_mes:String(card.first_mes ?? card.data?.first_mes ?? '')
    };
  }

  function blankRoot() {
    return {
      $meta:{
        schema_version:AVS.schemaVersion,
        state_revision:0,
        created_at:now(),
        updated_at:now(),
        last_success_at:null,
        last_scan_at:null,
        migrated_from_v2:false
      },
      manifest:{
        system_id:'avs_multiplayer_portrait_runtime',
        runtime_version:AVS.version,
        schema_version:AVS.schemaVersion,
        transport:'single_streaming_multiplayer_portrait_call',
        regex_required:false,
        display_mutation:false
      },
      characters:{},
      runtime:{
        active_character_ids:[],
        health:'READY',
        diagnostics:{
          helper_version:helperVersion(),
          generation_ended_events:0,
          message_received_events:0,
          watchdog_scans:0,
          assistant_turns_detected:0,
          api_calls:0,
          sync_attempts:0,
          sync_successes:0,
          processed_messages:0,
          batch_new_registered:0,
          batch_existing_updated:0,
          batch_rejected:0,
          updates_applied:0,
          last_batch_new:0,
          last_batch_updated:0,
          last_batch_rejected:0,
          last_error:null,
          last_error_stage:null,
          last_message_id:null,
          last_sync_reason:null,
          last_sync_started_at:null,
          last_sync_finished_at:null
        }
      }
    };
  }

  function validRoot(root) {
    return !!root && root.manifest?.system_id==='avs_multiplayer_portrait_runtime' && root.characters && root.runtime;
  }

  function readChatVars() {
    try { return getVariables({type:'chat'}) || {}; } catch (_) { return {}; }
  }

  function readRoot() {
    const v=readChatVars();
    return validRoot(v[AVS.namespace]) ? clone(v[AVS.namespace]) : null;
  }

  function profileLooksComplete(p) {
    if (!p || typeof p!=='object') return false;
    for (const k of ['face','body','natural_hair','outfit','hair_makeup','accessories','state']) {
      if (!p[k] || typeof p[k]!=='object') return false;
    }
    const acc=p.accessories||{};
    for (const k of ['headwear','forehead','hair','ears','neck','shoulders','arms','wrists','hands','fingers','chest','back','waist','hips','thighs','legs','ankles','feet']) {
      if (!Array.isArray(acc[k])) return false;
    }
    const st=p.state||{};
    for (const k of ['current_expression','current_overall_state','current_posture','current_gaze','current_gesture','current_motion','current_clothing_state','current_hair_state','current_makeup_state','current_accessory_state','current_hosiery_state','current_footwear_state','current_body_presentation','current_environment_effect','current_notes']) {
      if (typeof st[k]!=='string' || st[k].trim().length<6) return false;
    }
    return acc.headwear.length<=6;
  }

  function migrateLegacy(root, vars) {
    if (root.$meta.migrated_from_v2) return root;
    for (const ns of AVS.legacyNamespaces || []) {
      const old=vars?.[ns];
      if (!old?.characters || typeof old.characters!=='object') continue;
      for (const [id,c] of Object.entries(old.characters)) {
        if (!c?.identity?.name || !profileLooksComplete(c.profile)) continue;
        if (Object.values(root.characters).some(x=>normalizeName(x?.identity?.name).toLocaleLowerCase()===normalizeName(c.identity.name).toLocaleLowerCase())) continue;
        root.characters[id]={
          character_id:id,
          identity:clone(c.identity),
          admission:clone(c.admission||{}),
          profile:clone(c.profile),
          profile_complete:true,
          version:Number(c.version||1),
          created_at:c.created_at||now(),
          updated_at:c.updated_at||now(),
          migrated_from:ns
        };
        if (!root.runtime.active_character_ids.includes(id)) root.runtime.active_character_ids.push(id);
      }
    }
    if (Object.keys(root.characters).length) root.$meta.state_revision=Math.max(1,Number(root.$meta.state_revision||0));
    root.$meta.migrated_from_v2=true;
    return root;
  }


  async function writeRoot(root) {
    await updateVariablesWith(vars=>{
      root.$meta.updated_at=now();
      vars[AVS.namespace]=root;
      return vars;
    },{type:'chat'});
    return root;
  }

  function stripLegacyPerspectivePolicy(root) {
    if (!root || typeof root!=='object') return root;
    for (const c of Object.values(root.characters||{})) {
      if (c?.profile && Object.prototype.hasOwnProperty.call(c.profile,'presentation_mode')) {
        delete c.profile.presentation_mode;
      }
    }
    if (root.$meta) root.$meta.schema_version=AVS.schemaVersion;
    if (root.manifest) {
      root.manifest.runtime_version=AVS.version;
      root.manifest.schema_version=AVS.schemaVersion;
    }
    return root;
  }

  async function ensureRoot() {
    let root=readRoot();
    if (root) {
      root=stripLegacyPerspectivePolicy(root);
      await writeRoot(root);
      return root;
    }
    const vars=readChatVars();
    root=stripLegacyPerspectivePolicy(migrateLegacy(blankRoot(),vars));
    await writeRoot(root);
    return root;
  }

  function normalizeName(name) {
    return String(name ?? '').replace(/\s+/g,' ').trim().slice(0,80);
  }

  function characterIdFor(root,name) {
    const target=normalizeName(name).toLocaleLowerCase();
    for (const [id,c] of Object.entries(root.characters||{})) {
      if (normalizeName(c?.identity?.name).toLocaleLowerCase()===target) return id;
    }
    let base=`chr_${hashString(target)}`, id=base, i=2;
    while (root.characters[id]) id=`${base}_${i++}`;
    return id;
  }

  function buildRefs(root) {
    const active=root.runtime?.active_character_ids||[];
    const ids=Object.keys(root.characters||{}).sort((a,b)=>{
      const ai=active.indexOf(a),bi=active.indexOf(b);
      if (ai>=0||bi>=0) {
        if (ai<0) return 1;
        if (bi<0) return -1;
        return ai-bi;
      }
      return (Date.parse(root.characters[b]?.updated_at||0)||0)-(Date.parse(root.characters[a]?.updated_at||0)||0);
    });
    const refs={};
    ids.slice(0,AVS.limits.maxTrackedCharactersInPrompt).forEach((id,i)=>refs[`C${i+1}`]=id);
    return refs;
  }

  function compactGarmentName(x) {
    if (!x || x.status==='未穿着') return '未穿着';
    return String(x.full_name||x.name||'已穿着');
  }

  function compactCharacterState(c) {
    const p=c?.profile||{},f=p.face||{},b=p.body||{},n=p.natural_hair||{},o=p.outfit||{},h=p.hair_makeup||{},s=p.state||{};
    return {
      name:c.identity?.name,
      visual_age:c.identity?.visual_age,
      species:c.identity?.species,
      aesthetic:c.admission?.aesthetic,
      body_type:c.admission?.body_type,
      face:f.overall_aesthetic,
      height:b.height?.data||b.height?.form,
      hair_length:n.length?.data,
      hair_color:n.color?.data,
      hairstyle:h.hairstyle?.design,
      outerwear:compactGarmentName(o.outerwear),
      innerwear:compactGarmentName(o.innerwear),
      hosiery:compactGarmentName(o.hosiery),
      footwear:compactGarmentName(o.footwear),
      expression:s.current_expression,
      posture:s.current_posture,
      gaze:s.current_gaze,
      clothing_state:s.current_clothing_state,
      hair_state:s.current_hair_state
    };
  }

  function promptProjection(root) {
    const refs=buildRefs(root),out={};
    for (const [ref,id] of Object.entries(refs)) out[ref]=compactCharacterState(root.characters[id]);
    return safeJson(out);
  }

  function continuityPrompt(root) {
    return [
      '<AVS_VISUAL_CONTINUITY>',
      '以下仅是AVS视觉连续性事实。',
      '你在玩家可见回复中不得输出AVS机器JSON、AVS变量、VisualDelta或AVS技术说明。',
      '重要：如果角色卡或当前预设自己要求输出状态栏、选项栏、HTML、特殊格式或其他非AVS内容，必须照常遵守；AVS不得抑制、删除、替换或改写它们。',
      '已有明确视觉事实保持不变；只有剧情真实发生变化时才改变。',
      promptProjection(root),
      '</AVS_VISUAL_CONTINUITY>'
    ].join('\n');
  }

  async function beforeVisibleGeneration(type,option,dryRun) {
    if (dryRun || AVS.session.backgroundDepth>0 || !hasCharacterContext()) return;
    try {
      const root=await ensureRoot();
      uninjectPrompts(Object.values(AVS.promptIds));
      injectPrompts([
        {id:AVS.promptIds.continuity,position:'in_chat',depth:2,role:'system',content:continuityPrompt(root),should_scan:false},
        {id:AVS.promptIds.visibleGuard,position:'in_chat',depth:0,role:'system',content:'AVS后台会独立读取本轮正文。只禁止输出AVS自身的机器数据；角色卡/预设原有的状态栏、选项栏、HTML或格式要求不得被AVS影响。',should_scan:false}
      ],{once:true});
    } catch (err) {
      setHealth('DEGRADED','visible_prompt',err);
    }
  }

  function setHealth(health,stage,error=null) {
    AVS.session.health=health;
    AVS.session.lastError=error?String(error?.stack||error):null;
    AVS.session.lastErrorStage=stage||null;
    const root=readRoot();
    if (root) {
      root.runtime.health=health;
      root.runtime.diagnostics.last_error=AVS.session.lastError;
      root.runtime.diagnostics.last_error_stage=stage||null;
      writeRoot(root).catch(()=>{});
    }
  }

  function parseLooseJson(raw) {
    const text=String(raw ?? '').trim();
    const attempts=[
      text,
      text.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim(),
      text.replace(/^[\s\S]*?<json>\s*/i,'').replace(/\s*<\/json>[\s\S]*$/i,'').trim()
    ];
    for (const s of attempts) {
      try { return JSON.parse(s); } catch (_) {}
    }
    const start=text.indexOf('{');
    if (start<0) throw new Error('JSON object not found');
    let depth=0,inStr=false,esc=false;
    for (let i=start;i<text.length;i++) {
      const ch=text[i];
      if (inStr) {
        if (esc) esc=false;
        else if (ch==='\\') esc=true;
        else if (ch==='"') inStr=false;
        continue;
      }
      if (ch==='"') {inStr=true;continue;}
      if (ch==='{') depth++;
      else if (ch==='}') {
        depth--;
        if (depth===0) {
          const s=text.slice(start,i+1).replace(/,\s*([}\]])/g,'$1');
          try { return JSON.parse(s); } catch (_) {}
          break;
        }
      }
    }
    throw new Error('Invalid JSON response');
  }

  function normalizeGeneratedResult(result) {
    if (typeof result==='string') return result;
    if (result && typeof result==='object') {
      if (typeof result.content==='string') return result.content;
      if (typeof result.text==='string') return result.text;
    }
    return String(result ?? '');
  }

  function schemaSatisfied(value,schema) {
    if (!schema || typeof schema!=='object') return true;
    if (schema.enum && !schema.enum.includes(value)) return false;
    if (schema.type==='object') {
      if (!value || typeof value!=='object' || Array.isArray(value)) return false;
      for (const k of schema.required||[]) if (!Object.prototype.hasOwnProperty.call(value,k)) return false;
      for (const [k,sub] of Object.entries(schema.properties||{})) {
        if (Object.prototype.hasOwnProperty.call(value,k) && !schemaSatisfied(value[k],sub)) return false;
      }
      return true;
    }
    if (schema.type==='array') {
      if (!Array.isArray(value)) return false;
      if (Number.isFinite(schema.maxItems) && value.length>schema.maxItems) return false;
      if (Number.isFinite(schema.minItems) && value.length<schema.minItems) return false;
      return value.every(v=>schemaSatisfied(v,schema.items));
    }
    if (schema.type==='string') {
      if (typeof value!=='string') return false;
      if (Number.isFinite(schema.minLength) && value.length<schema.minLength) return false;
      return true;
    }
    if (schema.type==='number') return typeof value==='number' && Number.isFinite(value);
    if (schema.type==='integer') return Number.isInteger(value);
    if (schema.type==='boolean') return typeof value==='boolean';
    return true;
  }

  async function backgroundCall(kind,config,label='background') {
    const generationId=`avs-v24-${label}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
    const full={...config,generation_id:generationId};
    AVS.session.backgroundCalls.add(generationId);
    AVS.session.backgroundDepth++;
    let timer=null;
    try {
      const p=kind==='raw' ? generateRaw(full) : generate(full);
      const timeout=new Promise((_,reject)=>{
        timer=setTimeout(()=>{
          try { if (typeof stopGenerationById==='function') stopGenerationById(generationId); } catch (_) {}
          reject(new Error(`AVS_BACKGROUND_TIMEOUT:${label}`));
        },AVS.limits.backgroundTimeoutMs);
      });
      return await Promise.race([p,timeout]);
    } finally {
      if (timer) clearTimeout(timer);
      AVS.session.backgroundCalls.delete(generationId);
      AVS.session.backgroundDepth=Math.max(0,AVS.session.backgroundDepth-1);
    }
  }


  async function modelJson({system,user,schema,name}) {
    let lastErr=null;
    const canRaw=typeof generateRaw==='function';
    const canGen=typeof generate==='function';
    if (!canRaw && !canGen) throw new Error('Tavern Helper generate/generateRaw API unavailable');

    const base={should_stream:false,should_silence:true,max_chat_history:0};
    const strictSystem=system+'\n\n只输出一个合法JSON对象，不要Markdown代码围栏，不要解释。';
    const calls=[];

    // Plain JSON first: this works with the widest set of proxy/API/model combinations.
    if (canRaw) {
      calls.push({schema:false,run:()=>backgroundCall('raw',{...base,ordered_prompts:[{role:'system',content:strictSystem},{role:'user',content:user}]},`${name}-raw-json`)});
    }
    if (canRaw && schema && AVS.session.schemaSupport!=='unsupported') {
      calls.push({schema:true,run:()=>backgroundCall('raw',{...base,ordered_prompts:[{role:'system',content:system},{role:'user',content:user}],json_schema:{name,value:schema}},`${name}-raw-schema`)});
    }
    if (canGen) {
      calls.push({schema:false,run:()=>backgroundCall('generate',{...base,preset_name:'in_use',user_input:user,injects:[{role:'system',content:strictSystem,position:'in_chat',depth:0,should_scan:false}]},`${name}-gen-json`)});
    }
    if (canGen && schema && AVS.session.schemaSupport!=='unsupported') {
      calls.push({schema:true,run:()=>backgroundCall('generate',{...base,preset_name:'in_use',user_input:user,injects:[{role:'system',content:system,position:'in_chat',depth:0,should_scan:false}],json_schema:{name,value:schema}},`${name}-gen-schema`)});
    }

    for (let i=0;i<Math.min(calls.length,AVS.limits.modelAttempts);i++) {
      const call=calls[i];
      try {
        const raw=normalizeGeneratedResult(await call.run());
        const parsed=parseLooseJson(raw);
        if (schema && !schemaSatisfied(parsed,schema)) throw new Error('background JSON does not satisfy schema');
        if (call.schema) AVS.session.schemaSupport='supported';
        return parsed;
      } catch (err) {
        lastErr=err;
        const msg=String(err?.message||err);
        if (call.schema && /schema|response.?format|unsupported|not support|invalid.*json/i.test(msg)) AVS.session.schemaSupport='unsupported';
        console.warn('[AVS v2.5.1] background JSON attempt failed',i+1,name,err);
      }
    }
    throw lastErr || new Error('All background JSON methods failed');
  }

  const CANDIDATE_SCHEMA={
    type:'object',additionalProperties:false,
    properties:{
      candidates:{type:'array',items:{
        type:'object',additionalProperties:false,
        properties:{
          name:{type:'string'},
          is_specific_character:{type:'boolean'},
          is_female:{type:'boolean'},
          relevance:{type:'string',enum:['primary','important','plot_required','special_identity','recurring','none']},
          explicit_disqualifier:{type:'boolean'},
          disqualifier_reason:{type:'string'},
          evidence:{type:'string'}
        },
        required:['name','is_specific_character','is_female','relevance','explicit_disqualifier','disqualifier_reason','evidence']
      }},
      updates:{type:'array',items:{
        type:'object',additionalProperties:false,
        properties:{
          character_ref:{type:'string'},
          path:{type:'string'},
          value_json:{type:'string'},
          evidence:{type:'string'}
        },
        required:['character_ref','path','value_json','evidence']
      }}
    },
    required:['candidates','updates']
  };

  const ADMISSION_SCHEMA={
    type:'object',additionalProperties:false,
    properties:{
      pass:{type:'boolean'},
      reason:{type:'string'},
      visual_age_min:{type:'number'},
      visual_age_max:{type:'number'},
      aesthetic:{type:'string',enum:['beautiful','cute']},
      body_type:{type:'string',enum:['hourglass','pear']},
      species_class:{type:'string',enum:['human','humanoid','special_humanoid']},
      species:{type:'string'},
      allowed_features:{type:'array',items:{type:'string'}}
    },
    required:['pass','reason','visual_age_min','visual_age_max','aesthetic','body_type','species_class','species','allowed_features']
  };

  const textSchema=(min=1)=>({type:'string',minLength:min});
  const objSchema=props=>({type:'object',additionalProperties:false,properties:props,required:Object.keys(props)});
  const formBeauty=()=>objSchema({form:textSchema(),beauty:textSchema(4)});
  const formDataBeauty=()=>objSchema({form:textSchema(),data:textSchema(),beauty:textSchema(4)});
  const dataBeauty=()=>objSchema({data:textSchema(),beauty:textSchema(4)});
  const designBeauty=()=>objSchema({design:textSchema(),beauty:textSchema(4)});
  const wearSchema=fit=>objSchema({
    status:{type:'string',enum:['穿着','未穿着']},
    full_name:textSchema(),
    design:textSchema(),
    beauty:textSchema(),
    ...(fit?{fit_and_silhouette:textSchema()}:{})
  });
  const makeupSchema=()=>objSchema({status:{type:'string',enum:['着妆','未着妆']},design:textSchema(),beauty:textSchema()});
  const accItem=objSchema({full_name:textSchema(),design:textSchema(),beauty:textSchema()});
  const accArray=max=>({type:'array',maxItems:max,items:accItem});

  const PROFILE_SCHEMAS={
    face_hair:objSchema({
      face:objSchema({
        overall_aesthetic:textSchema(2),face_shape:formBeauty(),forehead:designBeauty(),cheekbones:designBeauty(),
        jawline:designBeauty(),chin:designBeauty(),eyebrows:formBeauty(),eyelashes:designBeauty(),eyes:formBeauty(),
        iris:designBeauty(),pupil:designBeauty(),nose:designBeauty(),lips:designBeauty(),skin_tone:dataBeauty(),skin_texture:dataBeauty()
      }),
      natural_hair:objSchema({length:dataBeauty(),color:dataBeauty()})
    }),
    body:objSchema({
      body:objSchema({
        body_type:formDataBeauty(),height:formDataBeauty(),head_body_ratio:formDataBeauty(),shoulders:formDataBeauty(),
        clavicle:formDataBeauty(),bust:formDataBeauty(),waist:formDataBeauty(),pelvis:formDataBeauty(),hips:formDataBeauty(),
        buttocks:formDataBeauty(),neck:dataBeauty(),back_curve:dataBeauty(),abdomen:dataBeauty(),upper_arms:dataBeauty(),
        forearms:dataBeauty(),hands:dataBeauty(),fingers:dataBeauty(),thighs:dataBeauty(),knees:dataBeauty(),calves:dataBeauty(),
        ankles:dataBeauty(),leg_length:dataBeauty(),feet:dataBeauty(),skin_tone:dataBeauty(),skin_texture:dataBeauty()
      })
    }),
    outfit:objSchema({
      outfit:objSchema({
