  function currentCardText() {
    const c=currentCardInfo();
    if (!c) return '';
    return [
      `当前角色卡标签：${c.name}`,
      c.description?`角色描述：${c.description}`:'',
      c.personality?`性格：${c.personality}`:'',
      c.scenario?`场景：${c.scenario}`:'',
      c.first_mes?`开场：${c.first_mes}`:''
    ].filter(Boolean).join('\n');
  }

  function getMessage(messageId) {
    const id=Number(messageId);
    if (Number.isFinite(id)) {
      try {
        const m=getChatMessages(id)?.[0];
        if (m) return m;
      } catch (_) {}
      const raw=ctx()?.chat?.[id];
      if (raw) return {message_id:id,role:raw.is_user?'user':'assistant',message:String(raw.mes??'')};
    }
    return null;
  }

  function latestAssistantMessage() {
    try {
      const m=getChatMessages(-1)?.[0];
      if (m?.role==='assistant' && String(m.message||'').trim()) return m;
    } catch (_) {}
    const all=getAllMessages();
    for (let i=all.length-1;i>=0;i--) {
      const m=all[i];
      if (m.role==='assistant' && String(m.message||'').trim()) return m;
    }
    return null;
  }

  async function waitForAssistantMessage(messageId,timeoutMs=AVS.limits.messageReadyTimeoutMs) {
    const started=Date.now();
    while (Date.now()-started<timeoutMs) {
      const direct=getMessage(messageId);
      if (direct?.role==='assistant' && String(direct.message||'').trim()) return direct;
      const latest=latestAssistantMessage();
      if (latest && (!Number.isFinite(Number(messageId)) || Number(latest.message_id)===Number(messageId))) return latest;
      await new Promise(r=>setTimeout(r,100));
    }
    const direct=getMessage(messageId);
    if (direct?.role==='assistant' && String(direct.message||'').trim()) return direct;
    return latestAssistantMessage();
  }

  function getAllMessages() {
    try {
      const arr=getChatMessages('0-{{lastMessageId}}',{role:'all',hide_state:'all'});
      if (Array.isArray(arr) && arr.length) return arr;
    } catch (_) {}
    return (ctx()?.chat||[]).map((m,i)=>({message_id:i,role:m.is_user?'user':'assistant',message:String(m.mes??'')}));
  }


  function previousUserText(messageId) {
    const all=getAllMessages();
    for (let i=all.length-1;i>=0;i--) {
      const m=all[i];
      if (Number(m.message_id)>=Number(messageId)) continue;
      if (m.role==='user') return String(m.message||'');
    }
    return '';
  }

  function prefixHashFor(messageId) {
    const all=getAllMessages().filter(m=>Number(m.message_id)<=Number(messageId));
    return hashString(all.map(m=>`${m.role}:${m.message}`).join('\n\u241e\n'));
  }

  function readCapture(messageId) {
    try { return clone(getVariables({type:'message',message_id:Number(messageId)})?.[AVS.captureKey] || null); }
    catch (_) { return null; }
  }

  async function writeCapture(messageId,capture) {
    try {
      await insertOrAssignVariables({[AVS.captureKey]:capture},{type:'message',message_id:Number(messageId)});
    } catch (err) {
      console.warn('[AVS v2.5.1] capture write failed',err);
    }
  }

  function candidateAnchored(name,context) {
    const n=normalizeName(name);
    if (!n) return false;
    return String(context).includes(n);
  }

  async function analyzeContext({messageId=null,assistantText='',userText='',root,cardOnly=false}) {
    const refs=buildRefs(root);
    const refNames=Object.fromEntries(Object.entries(refs).map(([r,id])=>[r,root.characters[id]?.identity?.name]));
    const context=[currentCardText(),userText,assistantText].filter(Boolean).join('\n\n');
    const system=[
      '你是AVS后台候选角色与动态变化分析器。只返回JSON。',
      '候选登记阶段只识别“具体人物”，绝不能把角色卡标题、主题、世界、地点、组织、物品、章节名或普通无剧情价值路人当成角色。',
      '候选角色必须明确是女性/雌性，并且具有主要、重要、剧情需要、特殊身份或常驻价值。',
      '这是在玩家可见回复已经完整生成之后进行的后台同步。不要因为正文没写身高、体型或外貌年龄就丢掉合格候选；这些视觉缺项会在下一阶段设计补全。',
      '如果正文明确说明该角色视觉年龄超过32、明确低颜值/不符合美丽或娇俏可爱、明确体型不可能为沙漏/梨型，标记explicit_disqualifier=true。',
      'updates只针对已经登记的C引用。必须逐项检查外貌、身体、自然头发、穿搭、发妆、18类配饰、表情、姿势、目光、动作以及服装/头发/妆容/配饰/丝袜/鞋履状态；本轮真实发生变化的字段必须更新，没有变化的稳定事实不得漂移。value_json必须是合法JSON字面量字符串。',
      `已有角色：${safeJson(refNames)}`,
      `当前状态：${promptProjection(root)}`
    ].join('\n\n');

    const user=[
      cardOnly?'只分析当前角色卡是否包含一个可登记的具体女性角色。':'分析本轮正文。',
      `当前角色卡信息：\n${currentCardText()||'无'}`,
      userText?`上一条玩家消息：\n${userText}`:'',
      assistantText?`本轮AI正文：\n${assistantText}`:''
    ].filter(Boolean).join('\n\n');

    const out=await modelJson({system,user,schema:CANDIDATE_SCHEMA,name:'avs_candidate_analysis'});
    out.candidates=Array.isArray(out.candidates)?out.candidates:[];
    out.updates=Array.isArray(out.updates)?out.updates:[];
    out.candidates=out.candidates.filter(c=>
      c && c.is_specific_character===true && c.is_female===true &&
      ['primary','important','plot_required','special_identity','recurring'].includes(c.relevance) &&
      c.explicit_disqualifier!==true &&
      candidateAnchored(c.name,context)
    ).slice(0,AVS.limits.maxNewCharactersPerMessage);
    out.updates=out.updates.filter(u=>u && refs[u.character_ref] && safeUpdatePath(u.path));
    return out;
  }

  async function resolveAdmission(candidate,sourceContext) {
    const system=[
      '你是AVS角色准入与视觉基础设计器，只返回JSON。',
      '角色已经通过“具体女性且有持续剧情价值”的候选门。现在判断并完成视觉准入。',
      '硬条件：外貌年龄最大值≤32；审美只能是beautiful或cute；体型只能是hourglass或pear。',
      '如果原文有明确冲突事实，pass=false。若原文没有写视觉年龄/审美/体型，但没有冲突，可以为这个需要持续设计的女性角色合理补全成合规值，并pass=true。',
      '人类/类人/特殊类人按species_class输出。类人仅允许角、耳朵、翅膀、尾巴四类非人特征。',
      '不要把普通路人升级成重要角色。'
    ].join('\n');
    const user=`候选：${safeJson(candidate)}\n\n上下文：\n${sourceContext}`;
    const a=await modelJson({system,user,schema:ADMISSION_SCHEMA,name:'avs_admission'});
    if (!a || a.pass!==true) return null;
    const min=Number(a.visual_age_min),max=Number(a.visual_age_max);
    if (!Number.isFinite(min)||!Number.isFinite(max)||min<0||max<min||max>32) return null;
    if (!['beautiful','cute'].includes(a.aesthetic)) return null;
    if (!['hourglass','pear'].includes(a.body_type)) return null;
    if (!['human','humanoid','special_humanoid'].includes(a.species_class)) return null;
    const allowed=new Set(['horns','ears','wings','tail','角','耳朵','翅膀','尾巴']);
    const features=Array.isArray(a.allowed_features)?a.allowed_features:[];
    if (features.some(x=>!allowed.has(String(x)))) return null;
    if (a.species_class==='human' && features.length) return null;
    return {
      visual_age:{min,max},
      aesthetic:a.aesthetic,
      body_type:a.body_type,
      species_class:a.species_class,
      species:String(a.species||a.species_class),
      allowed_features:clone(features),
      reason:String(a.reason||'')
    };
  }


  function deepMerge(base, incoming) {
    if (!incoming || typeof incoming!=='object') return base;
    for (const [k,v] of Object.entries(incoming)) {
      if (Array.isArray(v)) {
        base[k]=clone(v);
      } else if (v && typeof v==='object') {
        if (!base[k] || typeof base[k]!=='object' || Array.isArray(base[k])) base[k]={};
        deepMerge(base[k],v);
      } else if (v!==undefined && v!==null && v!=='') {
        base[k]=v;
      }
    }
    return base;
  }

