      head_body_ratio:formData(body.head_ratio?`${body.head_ratio}头身左右的修长比例`:'修长协调的头身比例',body.head_ratio?`约${body.head_ratio}头身`:'约7.3—7.8头身'),
      shoulders:formData(body.shoulders||'柔和自然的肩型',cm(body.shoulder_width_cm,'肩宽约')),
