      bust:formData(body.bust||'圆润挺拔且与整体比例协调',body.bust_data||'尺寸与肩腰比例协调'),
      waist:formData(body.waist||'纤细收束的腰型',cm(body.waist_cm,'腰围约')),
      pelvis:formData(body.pelvis||'女性化、圆润协调的骨盆结构',body.pelvis_data||'与腰臀和大腿比例自然衔接'),
      hips:formData(body.hips||'圆润顺滑的胯线',body.hip_cm?`臀胯围约${body.hip_cm}厘米`:'胯宽与肩线、腰线协调'),
