      upper_arms:data(body.upper_arms||'上臂围度纤细协调'),
      forearms:data(body.forearms||'前臂线条修长'),
      hands:data(body.hands||'手掌小巧匀称'),
      fingers:data(body.fingers||'手指修长、指节细致'),
      thighs:data(body.thigh_cm?`大腿围约${body.thigh_cm}厘米；${body.thighs||'圆润饱满'}`:(body.thighs||'大腿圆润饱满且与胯臀自然衔接')),
      knees:data(body.knees||'膝部轮廓小巧自然'),
