        exposure:String(x.exposure||'按衣长、开口和透明度记录可见肌肤边界，不额外制造暴露'),
        wearing_feel:String(x.feel||x.wearing_feel||'记录材质接触、支撑、束缚、摩擦、温度与动作时的体感'),
