      silhouette:{design:String(outfit.silhouette||'服装轮廓与角色身形和场景协调'),beauty:beautySentence(outfit.silhouette)},
      neckline:{design:String(outfit.neckline||'领口结构服从当前服装设计'),beauty:beautySentence(outfit.neckline)},
      sleeves:{design:String(outfit.sleeves||'袖型结构服从当前服装设计'),beauty:beautySentence(outfit.sleeves)},
