      lower_structure:{design:String(outfit.lower_structure||'下装结构与整体造型协调'),beauty:beautySentence(outfit.lower_structure)},
      layers:{design:String(outfit.layers||'层叠关系清楚并避免无意义堆叠'),beauty:beautySentence(outfit.layers)},
      materials:{design:String(outfit.materials||'材质以正文已知与角色身份为准'),beauty:beautySentence(outfit.materials)},
      colors:{design:String(outfit.colors||'配色与角色气质及场景协调'),beauty:beautySentence(outfit.colors)},
      patterns:{design:String(outfit.patterns||'纹样服从主题与身份，不强行添加'),beauty:beautySentence(outfit.patterns)},
      decorations:{design:String(outfit.decorations||'装饰细节服从整体视觉重点'),beauty:beautySentence(outfit.decorations)}
    };
    for (const key of ['outerwear','innerwear','bra','panties','hosiery']) {
      const item=wearItem(outfit[key]);
      if (item) out.outfit[key]=item;
    }
    const foot=shoes(outfit.footwear);
    if (foot) out.outfit.footwear=foot;

    const makeupItem=(x)=>{
      if (!x || x===false || x==='未着妆' || x.status==='未着妆') return null;
      if (typeof x==='string') return {status:'着妆',design:x,beauty:beautySentence(x)};
      return {status:'着妆',design:String(x.design||x.name||'当前妆容'),beauty:String(x.beauty||beautySentence(x.design||x.name))};
    };
    out.hair_makeup={
      hairstyle:{design:String(hair.hairstyle||'当前发型依据自然发长和角色气质整理'),beauty:beautySentence(hair.hairstyle)},
      bangs:{design:String(hair.bangs||'刘海与当前发型自然衔接'),beauty:beautySentence(hair.bangs)},
      hair_beauty_summary:String(hair.summary||'整体发型柔顺协调，与角色脸型和气质相互衬托。'),
      makeup_beauty_summary:String(makeup.summary||'妆容以提升角色气质为主，保持精致而不过分夸张。')
    };
    for (const [srcKey,dstKey] of [['base','base_makeup'],['eye','eye_makeup'],['brow','brow_makeup'],['blush','blush'],['lip','lip_makeup'],['huadian','huadian']]) {
