    }

    const accSlots=['headwear','forehead','hair','ears','neck','shoulders','arms','wrists','hands','fingers','chest','back','waist','hips','thighs','legs','ankles','feet'];
    out.accessories=Object.fromEntries(accSlots.map(k=>[k,[]]));
    const pushAcc=(slot,x)=>{
      if (!accSlots.includes(slot) || !x) return;
      const arr=out.accessories[slot];
      if (slot==='headwear' && arr.length>=6) return;
      if (typeof x==='string') arr.push({full_name:x,specifications:'尺寸、材质、连接方式与表面工艺按当前造型记录',design:`${x}在${slot}位置以结构、材质和细节完成造型呼应`,beauty:beautySentence(x),character_effect:'通过视觉焦点、身份暗示与比例关系衬托角色'});
      else arr.push({full_name:String(x.name||x.full_name||'装饰'),specifications:String(x.specs||x.specifications||'尺寸、材质、连接方式与表面工艺按当前造型记录'),design:String(x.design||'结构与当前造型协调'),beauty:String(x.aesthetics||x.beauty||beautySentence(x.name||x.full_name)),character_effect:String(x.effect||x.character_effect||'通过视觉焦点、身份暗示与比例关系衬托角色')});
    };
    if (Array.isArray(seed.accessories)) {
      for (const x of seed.accessories) pushAcc(String(x?.slot||''),x);
    } else if (seed.accessories && typeof seed.accessories==='object') {
      for (const [slot,items] of Object.entries(seed.accessories)) for (const x of (Array.isArray(items)?items:[])) pushAcc(slot,x);
    }
    const hairAcc=out.accessories.hair.slice(0,6);
    if (hairAcc.length) out.hair_makeup.hair_accessories={status:'佩戴',items:clone(hairAcc)};

    const stateMap={
      expression:'current_expression',overall:'current_overall_state',posture:'current_posture',gaze:'current_gaze',
      gesture:'current_gesture',motion:'current_motion',clothing:'current_clothing_state',hair:'current_hair_state',
      makeup:'current_makeup_state',accessories:'current_accessory_state',hosiery:'current_hosiery_state',
      footwear:'current_footwear_state',body:'current_body_presentation',environment:'current_environment_effect',notes:'current_notes'
    };
    out.state={};
    for (const [src,dst] of Object.entries(stateMap)) if (state[src]) out.state[dst]=String(state[src]);
    return out;
  }


  function completeProfileLocally(profile,admission,designSeed={}) {
    const merged=deepMerge(fallbackProfile(admission),compactDesignToProfile(designSeed||{},admission));
    deepMerge(merged,profile||{});
    normalizeAbsent(merged);
    if (merged.outfit) for (const k of ['neckline','sleeves','waist_structure','lower_structure','layers','materials','colors','patterns','decorations']) delete merged.outfit[k];
    return merged;
  }

  function normalizeAbsent(profile) {
    const p=profile;
    for (const k of ['outerwear','innerwear','bra','panties','hosiery']) {
      const x=p?.outfit?.[k];
      if (x?.status==='未穿着') {
        x.full_name='未穿着';x.specifications='未穿着';x.design='未穿着';x.beauty='未穿着';x.coverage='未穿着';x.exposure='未穿着';x.wearing_feel='未穿着';x.character_effect='未穿着';
      }
    }
    const f=p?.outfit?.footwear;
    if (f?.status==='未穿着') {
      f.full_name='未穿着';f.specifications='未穿着';f.design='未穿着';f.beauty='未穿着';f.character_effect='未穿着';f.left_state='未穿着';f.right_state='未穿着';
    }
    for (const k of ['base_makeup','eye_makeup','brow_makeup','blush','lip_makeup','huadian']) {
      const x=p?.hair_makeup?.[k];
      if (x?.status==='未着妆') {x.design='未着妆';x.beauty='未着妆';}
    }
    const n=p?.hair_makeup?.nails;
    if (n?.status==='未着色') {n.color_and_gloss='未着色';n.beauty='未着色';}
    return p;
  }

  function sectionPrompt(kind,name,admission,sourceContext,existingProfile=null) {
    const common=[
      '你是AVS后台视觉档案设计器，只返回JSON。',
      `角色：${name}`,
      `准入信息：${safeJson(admission)}`,
      '所有玩家可见描述值必须使用简体中文。',
      '保护来源中已经明确的事实；缺失的视觉信息可以按商业二次元ACGN审美主动设计补全。',
      '当前不存在的穿搭、妆容或配饰不得凭空说成正在穿/正在画/正在戴；必须用“未穿着”“未着妆”或空数组。',
      '不写露骨色情内容；服装贴合只描述剪裁、包覆轮廓和视觉塑形。',
      existingProfile?`已有档案：${safeJson(existingProfile)}`:'',
      `上下文：\n${sourceContext}`
    ].filter(Boolean);

    const rules={
      face_hair:'生成外貌与自然头发。脸型、眉型、眼型必须“具体形态+自然语言美化”；其余外貌项目写具体设计/数据与美感。',
      body:'生成身体。体型、身高、头身比、肩部、锁骨、胸部、腰部、骨盆、胯部、臀部必须“具体形态+精准数据+自然语言美化”；其余身体项目“精准数据+自然语言美化”。',
      outfit:'生成当前穿搭。外衣、内搭、胸罩、内裤、丝袜=完整名称+设计介绍+美感语言+非露骨包覆与轮廓；鞋履=完整名称+设计介绍+美感语言。没穿必须明确未穿着。',
      hair_makeup_accessories:'生成当前发妆与18类配饰。妆容必须拆分底妆、眼妆、眉妆、腮红、唇妆、花钿。配饰完整覆盖18类；未佩戴用空数组；头饰最多6件；每件配饰=完整名称+设计介绍+美感语言。',
      state:'生成当前状态。每项必须是细致、可想象的自然语言，包含当前表情、整体状态、姿势、目光、手势、动作、服装/头发/妆容/配饰/丝袜/鞋履状态、身体呈现、环境影响等；禁止只写“正常”。'
    };
    common.push(rules[kind]);
    return common.join('\n\n');
  }

  async function buildFullProfile(name,admission,sourceContext,existingProfile=null) {
    const merged={};
    for (const kind of ['face_hair','body','outfit','hair_makeup_accessories','state']) {
      let lastErr=null;
      for (let attempt=0;attempt<2;attempt++) {
        try {
          const part=await modelJson({
            system:sectionPrompt(kind,name,admission,sourceContext,existingProfile),
            user:`生成${kind}部分。`,
            schema:PROFILE_SCHEMAS[kind],
            name:`avs_profile_${kind}`
          });
          Object.assign(merged,part);
          lastErr=null;
          break;
        } catch (err) { lastErr=err; }
      }
      if (lastErr) throw new Error(`profile section ${kind} failed: ${lastErr}`);
    }
    normalizeAbsent(merged);
    if (!profileLooksComplete(merged)) throw new Error('combined profile validation failed');
    return merged;
  }

  function safeUpdatePath(path) {
    const p=String(path||'');
    if (!/^profile\.(face|body|natural_hair|outfit|hair_makeup|accessories|state)(?:\.[A-Za-z0-9_\u4e00-\u9fff-]+)*$/.test(p)) return false;
    return !/(?:^|\.)(__proto__|prototype|constructor)(?:\.|$)/.test(p);
  }

  function parseValueJson(text) {
    try { return parseLooseJson(String(text)); } catch (_) {}
    const s=String(text||'').trim();
    try { return JSON.parse(s); } catch (_) {}
    return s;
  }

  function getAt(obj,path) {
    return String(path).split('.').reduce((a,k)=>a==null?undefined:a[k],obj);
  }

  function setAt(obj,path,value) {
    const parts=String(path).split('.');
    let cur=obj;
    for (let i=0;i<parts.length-1;i++) {
      const k=parts[i];
      if (!cur[k]||typeof cur[k]!=='object'||Array.isArray(cur[k])) cur[k]={};
      cur=cur[k];
    }
    cur[parts.at(-1)]=clone(value);
  }

  function makeRecord(root,candidate,admission,profile) {
    const id=characterIdFor(root,candidate.name);
    return {
      character_id:id,
      identity:{
        name:normalizeName(candidate.name),
        sex:'女性',
        species:admission.species,
        species_class:admission.species_class,
        visual_age:clone(admission.visual_age)
      },
      admission:{
        status:'pass',
        aesthetic:admission.aesthetic,
        body_type:admission.body_type,
        role_relevance:candidate.relevance,
        allowed_features:clone(admission.allowed_features),
        evidence:{candidate:candidate.evidence,admission:admission.reason},
        reviewed_at:now()
      },
      profile:clone(profile),
      profile_complete:true,
      version:1,
      created_at:now(),
      updated_at:now()
    };
  }

  function applyUpdate(root,update,refs) {
    const id=refs[update.character_ref], c=root.characters[id];
    if (!c || !safeUpdatePath(update.path)) return null;
    const value=parseValueJson(update.value_json);
    const old=clone(getAt(c,update.path));
    if (JSON.stringify(old)===JSON.stringify(value)) return null;
    setAt(c,update.path,value);
    c.version=Number(c.version||0)+1;
    c.updated_at=now();
    return {character_id:id,path:update.path,old_value:old,new_value:clone(value),evidence:update.evidence};
  }


  function recentTranscript(limit=AVS.limits.recentTranscriptMessages) {
    const all=getAllMessages().slice(-Math.max(2,Number(limit)||16));
    return all.map(m=>`${m.role==='assistant'?'AI':'玩家'}：${String(m.message||'')}`).join('\n\n');
  }

  function validateBatchAdmission(item) {
    if (!item || item.sex!=='female') return null;
    const a=item.admission||{};
    if (a.pass!==true) return null;
    const min=Number(a.visual_age_min),max=Number(a.visual_age_max);
    if (!Number.isFinite(min)||!Number.isFinite(max)||min<0||max<min||max>32) return null;
    if (!['beautiful','cute'].includes(a.aesthetic)) return null;
    if (!['hourglass','pear'].includes(a.body_type)) return null;
    if (!['primary','important','plot_required','special_identity','recurring'].includes(item.role_relevance)) return null;
    if (!['human','humanoid','special_humanoid'].includes(a.species_class)) return null;
    const allowed=new Set(['horns','ears','wings','tail','角','耳朵','翅膀','尾巴']);
    const features=Array.isArray(a.allowed_features)?a.allowed_features:[];
    if (features.some(x=>!allowed.has(String(x)))) return null;
    if (a.species_class==='human'&&features.length) return null;
    return {
      visual_age:{min,max},
      aesthetic:a.aesthetic,
      body_type:a.body_type,
      species_class:a.species_class,
