  async function singleApiJson(system,user,label='batch-sync') {
    const canRaw=typeof generateRaw==='function';
    const canGen=typeof generate==='function';
    if (!canRaw&&!canGen) throw new Error('AVS_NO_GENERATION_API');

    // v2.5 deliberately streams the hidden call. The user's log showed stream:false
    // together with a server-side AbortError; a large non-streaming JSON body can
    // sit idle long enough for a proxy/socket to be aborted. Streaming keeps data flowing.
    const common={
      should_stream:true,
      should_silence:true,
      max_chat_history:0,
      custom_api:{
        max_tokens:AVS.limits.backgroundMaxTokens,
        temperature:0.2,
        top_p:0.9
      }
    };
    const strictSystem=system+'\n\n只输出一个合法JSON对象。禁止Markdown代码围栏、解释文字、角色扮演正文、预设状态栏或选项栏。';
    let raw;
    if (canRaw) {
      raw=await backgroundCall('raw',{
        ...common,
        user_input:avsWorldbookRouteInput(),
        ordered_prompts:[
          'world_info_before',
          {role:'system',content:strictSystem},
          'world_info_after',
          {role:'user',content:user}
        ]
      },label);
    } else {
      raw=await backgroundCall('generate',{
        ...common,
        preset_name:'in_use',
        user_input:user,
        injects:[{role:'system',content:strictSystem,position:'in_chat',depth:0,should_scan:true}]
      },label);
    }
    return parseLooseJson(normalizeGeneratedResult(raw));
  }


  async function runSingleBatchSync(messageId,root) {
    const {system,user,refs}=batchSyncPrompt(root,messageId);
    root.runtime.diagnostics.api_calls++;
    await writeRoot(root);
    const out=await singleApiJson(system,user,`turn-${messageId}`);
    return {out,refs};
  }

