  async function processAssistant(messageId,{force=false,reason='event'}={}) {
    messageId=Number(messageId);
    if (!hasCharacterContext() || AVS.session.processing.has(messageId)) return;
    const m=getMessage(messageId);
    if (!m || m.role!=='assistant' || !String(m.message||'').trim()) return;

    const sourceHash=hashString(m.message);
    const prefixHash=prefixHashFor(messageId);
    const oldCap=readCapture(messageId);
    if (!force && oldCap?.schema_version===AVS.schemaVersion && oldCap.source_hash===sourceHash && oldCap.prefix_hash===prefixHash && ['complete','failed'].includes(oldCap.status)) return;

    AVS.session.processing.add(messageId);
    try {
      let root=await ensureRoot();
      root.runtime.diagnostics.assistant_turns_detected++;
      root.runtime.diagnostics.sync_attempts++;
      root.runtime.diagnostics.last_message_id=messageId;
      root.runtime.diagnostics.last_sync_reason=reason;
      root.runtime.diagnostics.last_sync_started_at=now();
      root.runtime.health='PROCESSING';
      root.$meta.last_scan_at=now();
      await writeRoot(root);

      let batch,refs;
      try {
        ({out:batch,refs}=await runSingleBatchSync(messageId,root));
      } catch (err) {
        root=await ensureRoot();
        root.runtime.health='DEGRADED';
        root.runtime.diagnostics.last_error=String(err?.stack||err);
        root.runtime.diagnostics.last_error_stage='single_api_batch';
        root.runtime.diagnostics.last_sync_finished_at=now();
        await writeRoot(root);
        await writeCapture(messageId,{
          schema_version:AVS.schemaVersion,status:'failed',source_hash:sourceHash,prefix_hash:prefixHash,
          attempted_at:now(),reason:String(err),sync_reason:reason
        });
        setHealth('DEGRADED','single_api_batch',err);
        return;
      }

      const newItems=Array.isArray(batch?.new_characters)?batch.new_characters.slice(0,AVS.limits.maxNewCharactersPerSync):[];
      const updateItems=Array.isArray(batch?.updates)?batch.updates:[];
      const registrations=[],patches=[];
      let rejected=0,updatedCharacters=0;

      const context=[currentCardText(),previousUserText(messageId),String(m.message||'')].join('\n\n');

      for (const item of newItems) {
        try {
          const name=normalizeName(item?.name);
          if (!name || !candidateAnchored(name,context)) {rejected++;continue;}
          if (root.characters[characterIdFor(root,name)]) continue;
          const admission=validateBatchAdmission(item);
          if (!admission) {rejected++;continue;}
          const profile=completeProfileLocally(item.profile,admission,item.design||{});
          if (!profileLooksComplete(profile)) {rejected++;continue;}
          const record=makeRecord(root,{name,relevance:item.role_relevance,evidence:item?.evidence||item?.admission?.reason||''},admission,profile);
          record.profile_source='single_api_batch';
          root.characters[record.character_id]=record;
          if (!root.runtime.active_character_ids.includes(record.character_id)) root.runtime.active_character_ids.push(record.character_id);
          registrations.push(clone(record));
          root.runtime.diagnostics.batch_new_registered++;
        } catch (err) {
          rejected++;
          console.warn('[AVS v2.5.1] rejected new character item',err,item);
        }
      }

      const touched=new Set();
      for (const item of updateItems) {
        const id=refs?.[item?.character_ref];
        if (!id || !root.characters[id] || !Array.isArray(item?.changes)) {rejected++;continue;}
        for (const ch of item.changes) {
          if (!safeUpdatePath(ch?.path)) {rejected++;continue;}
          const old=clone(getAt(root.characters[id],ch.path));
          const value=clone(ch.value);
          if (JSON.stringify(old)===JSON.stringify(value)) continue;
          setAt(root.characters[id],ch.path,value);
          root.characters[id].version=Number(root.characters[id].version||0)+1;
          root.characters[id].updated_at=now();
          patches.push({character_id:id,path:ch.path,old_value:old,new_value:value});
          root.runtime.diagnostics.updates_applied++;
          touched.add(id);
        }
      }
      updatedCharacters=touched.size;
      root.runtime.diagnostics.batch_existing_updated+=updatedCharacters;
      root.runtime.diagnostics.batch_rejected+=rejected;
      root.runtime.diagnostics.last_batch_new=registrations.length;
      root.runtime.diagnostics.last_batch_updated=updatedCharacters;
      root.runtime.diagnostics.last_batch_rejected=rejected;

      if (registrations.length||patches.length) root.$meta.state_revision=Number(root.$meta.state_revision||0)+1;
      root.runtime.diagnostics.sync_successes++;
      root.runtime.diagnostics.processed_messages++;
      root.runtime.diagnostics.last_error=null;
      root.runtime.diagnostics.last_error_stage=null;
      root.runtime.diagnostics.last_sync_finished_at=now();
      root.runtime.health='READY';
      root.$meta.last_success_at=now();
      await writeRoot(root);

      await writeCapture(messageId,{
        schema_version:AVS.schemaVersion,status:'complete',source_hash:sourceHash,prefix_hash:prefixHash,
        registrations,patches,resulting_revision:root.$meta.state_revision,processed_at:now(),reason,
        batch_summary:{new_registered:registrations.length,existing_updated:updatedCharacters,rejected}
      });
      setHealth('READY',null,null);
    } finally {
      AVS.session.processing.delete(messageId);
    }
  }


