  function captureIsCurrent(cap,sourceHash,prefixHash) {
    if (!cap || cap.schema_version!==AVS.schemaVersion) return false;
    if (cap.source_hash!==sourceHash || cap.prefix_hash!==prefixHash) return false;
    if (['complete','failed'].includes(cap.status)) return true;
    return false;
  }

  async function replayValidCaptures() {
    const root=migrateLegacy(blankRoot(),readChatVars());
    const messages=getAllMessages();
    for (const m of messages) {
      if (m.role!=='assistant') continue;
      const cap=readCapture(m.message_id);
      if (!cap || cap.schema_version!==AVS.schemaVersion || cap.status!=='complete') continue;
      const sourceHash=hashString(m.message);
      const prefixHash=prefixHashFor(m.message_id);
      if (cap.source_hash!==sourceHash || cap.prefix_hash!==prefixHash) continue;
      for (const rec of cap.registrations||[]) {
        if (!rec?.character_id || !profileLooksComplete(rec.profile)) continue;
        root.characters[rec.character_id]=clone(rec);
        if (!root.runtime.active_character_ids.includes(rec.character_id)) root.runtime.active_character_ids.push(rec.character_id);
      }
      for (const p of cap.patches||[]) {
        const c=root.characters[p.character_id];
        if (!c || !safeUpdatePath(p.path)) continue;
        setAt(c,p.path,p.new_value);
        c.version=Number(c.version||0)+1;
        c.updated_at=now();
      }
      root.$meta.state_revision=Number(cap.resulting_revision||root.$meta.state_revision);
    }
    await writeRoot(root);
    return root;
  }

  async function reconcileHistory(reason='history') {
    if (!hasCharacterContext()) return;
    await replayValidCaptures();
    const latest=latestAssistantMessage();
    if (latest) await processAssistant(Number(latest.message_id),{force:true,reason:`reconcile:${reason}`});
    return await ensureRoot();
  }


  async function scanRecent({all=false}={}) {
    if (!hasCharacterContext()) return;
    const assistants=getAllMessages().filter(m=>m.role==='assistant');
    if (!assistants.length) return;
    const selected=all?assistants:[assistants.at(-1)];
    for (const m of selected) {
      const cap=readCapture(m.message_id);
      const sourceHash=hashString(m.message),prefixHash=prefixHashFor(m.message_id);
      const valid=captureIsCurrent(cap,sourceHash,prefixHash);
      if (!valid) await processAssistant(Number(m.message_id),{force:all,reason:all?'manual_full_rescan':'latest_detector'});
    }
  }


  function enqueue(fn) {
    AVS.session.queue=AVS.session.queue.then(fn,fn);
    return AVS.session.queue;
