  async function fullRescan() {
    if (!hasCharacterContext()) return {ok:false,code:'NO_CHARACTER_CONTEXT'};
    try {
      const fresh=blankRoot();
      fresh.$meta.migrated_from_v2=true;
      fresh.runtime.health='PROCESSING';
      fresh.runtime.diagnostics.last_sync_reason='manual_full_rescan';
      await writeRoot(fresh);

      const assistants=getAllMessages().filter(m=>m.role==='assistant');
      let completed=0,failed=0;
      for (const m of assistants) {
        await processAssistant(Number(m.message_id),{force:true,reason:'manual_full_rescan'});
        const cap=readCapture(m.message_id);
        if (cap?.schema_version===AVS.schemaVersion && cap.status==='complete') completed++;
        else failed++;
      }
      const root=await ensureRoot();
      if (root.runtime.health!=='DEGRADED') root.runtime.health='READY';
      await writeRoot(root);
      try { globalThis.toastr?.info?.(`AVS全量重扫完成：成功${completed}层，失败${failed}层。`,'AVS'); } catch (_) {}
      return {ok:true,completed,failed,characters:Object.values(root.characters||{}).length};
    } catch (err) {
      setHealth('DEGRADED','full_rescan',err);
      try { globalThis.toastr?.error?.('AVS全量重扫失败，详细错误已写入控制台。','AVS'); } catch (_) {}
      return {ok:false,error:String(err?.message||err)};
    }
  }


