  function on(event,fn,last=false) {
    if (!event) return;
    try { AVS.session.listeners.push((last?eventMakeLast:eventOn)(event,fn)); } catch (_) {}
  }

  on(tavern_events.APP_READY,onContext);
  on(tavern_events.CHAT_CHANGED,onContext);
  on(tavern_events.CHAT_CREATED,onContext);
  on(tavern_events.GENERATION_AFTER_COMMANDS,beforeVisibleGeneration,true);

  // Primary path: the visible reply is complete. AVS now synchronizes the full character state.
  on(tavern_events.GENERATION_ENDED,(id)=>{
    AVS.session.lastGenerationEndedId=Number(id);
    const root=readRoot();
    if (root) {
      root.runtime.diagnostics.generation_ended_events++;
      writeRoot(root).catch(()=>{});
    }
    setTimeout(()=>postTurnSync(Number(id),'GENERATION_ENDED'),650);
  },true);

  // Secondary path: some generation modes/providers emit MESSAGE_RECEIVED more reliably.
  on(tavern_events.MESSAGE_RECEIVED,(id,type)=>{
    const root=readRoot();
    if (root) {
      root.runtime.diagnostics.message_received_events++;
      writeRoot(root).catch(()=>{});
    }
    setTimeout(()=>postTurnSync(Number(id),`MESSAGE_RECEIVED:${type||'normal'}`),900);
  },true);

  // Rendering/update fallbacks cover first-message selection, reloads and extension-driven message replacement.
  if (tavern_events.CHARACTER_MESSAGE_RENDERED) {
    on(tavern_events.CHARACTER_MESSAGE_RENDERED,id=>{
      setTimeout(()=>postTurnSync(Number(id),'CHARACTER_MESSAGE_RENDERED'),700);
    },true);
  }
  if (tavern_events.MESSAGE_UPDATED) {
    on(tavern_events.MESSAGE_UPDATED,id=>{
      setTimeout(()=>postTurnSync(Number(id),'MESSAGE_UPDATED'),500);
    },true);
  }

  on(tavern_events.MESSAGE_SWIPED,()=>setTimeout(()=>enqueue(()=>reconcileHistory('swipe')),350));
  on(tavern_events.MESSAGE_EDITED,()=>setTimeout(()=>enqueue(()=>reconcileHistory('edit')),350));
  on(tavern_events.MESSAGE_DELETED,()=>setTimeout(()=>enqueue(()=>reconcileHistory('delete')),350));
  if (tavern_events.MESSAGE_SWIPE_DELETED) on(tavern_events.MESSAGE_SWIPE_DELETED,()=>setTimeout(()=>enqueue(()=>reconcileHistory('swipe_delete')),350));

  try {
    eventOn(getButtonEvent('AVS 状态'),status);
    eventOn(getButtonEvent('AVS 自检'),selfCheck);
    eventOn(getButtonEvent('AVS 全量重扫'),fullRescan);
  } catch (_) {}

  AVS.session.watchdog=setInterval(watchdogTick,AVS.limits.watchdogIntervalMs);

  AVS.stop=()=>{
    for (const h of AVS.session.listeners) try { h?.stop?.(); } catch (_) {}
    if (AVS.session.watchdog) clearInterval(AVS.session.watchdog);
    for (const t of AVS.session.retryTimers.values()) clearTimeout(t);
    AVS.session.retryTimers.clear();
    try { uninjectPrompts(Object.values(AVS.promptIds)); } catch (_) {}
    if (globalThis.__AVS_V25_RUNTIME__===AVS) delete globalThis.__AVS_V25_RUNTIME__;
  };

  AVS.api={
    readRoot,ensureRoot,buildRefs,profileLooksComplete,parseLooseJson,processAssistant,postTurnSync,waitForAssistantMessage,runSingleBatchSync,scanRecent,reconcileHistory,selfCheck,fullRescan
  };

  // 4.6.0 had a should_silence bug; this is diagnostic only because generateRaw/generate still return results.
  try {
    const hv=helperVersion();
    if (hv!=='unknown' && !semverGte(hv,'4.6.1')) console.warn('[AVS v2.5.1] Tavern Helper older than 4.6.1; upgrade is recommended.',hv);
  } catch (_) {}

  onContext().catch(err=>setHealth('DEGRADED','bootstrap',err));
  console.info('[AVS v2.5.1] Multiplayer Portrait Runtime 2.5.1 loaded.');
})();
